CREATE TABLE t1(x); CREATE TABLE t3(y); CREATE TABLE t4(z); CREATE TRIGGER tr1 INSERT ON t3 BEGIN UPDATE t3 SET y=z FROM (SELECT z FROM t4); END; CREATE TRIGGER tr2 INSERT ON t3 BEGIN UPDATE t3 SET y=abc FROM (SELECT x AS abc FROM t1); END; ALTER TABLE t1 RENAME TO t2; ALTER TABLE t2 RENAME x TO xx;